#!/usr/bin/python3
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

INVENTORY = [
    {"sku": "widget-a", "quantity": 42},
    {"sku": "widget-b", "quantity": 17},
]

class Handler(BaseHTTPRequestHandler):
    server_version = "inventory-api/1.0"

    def send_json(self, status, payload):
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        path = urlparse(self.path).path
        if path == "/health":
            self.send_json(200, {"service": "inventory-api", "status": "ok"})
        elif path == "/inventory":
            self.send_json(200, {"items": INVENTORY})
        elif path == "/":
            self.send_json(200, {"service": "inventory-api", "endpoints": ["/health", "/inventory"]})
        else:
            self.send_json(404, {"error": "not found"})

    def log_message(self, fmt, *args):
        print("%s - %s" % (self.address_string(), fmt % args), flush=True)

if __name__ == "__main__":
    ThreadingHTTPServer(("0.0.0.0", 8080), Handler).serve_forever()
ANTRIEB_INVENTORY_API
